[{"order":1,"type":"heading","text":"Custom Editor Scripting & Property Drawers in Unity"},{"order":2,"type":"paragraph","text":"Unity provides a powerful framework for extending the Editor to fit your specific game development workflow. By leveraging Custom Editors and Property Drawers, you can create intuitive, artist-friendly interfaces that replace standard, cluttered inspectors with clean, contextual tooling."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"Before writing editor code, remember that all scripts dealing with the Unity Editor must reside inside a folder named "Editor" to ensure they are not included in your game's final runtime build."},{"order":5,"type":"subheading","text":"Creating a Property Drawer"},{"order":6,"type":"paragraph","text":"Property Drawers allow you to customize how specific serializable classes or fields with custom attributes are rendered in the inspector without rewriting the entire component editor. First, let us create a custom attribute class."},{"order":7,"type":"code","text":"using UnityEngine;

public class RangeBarAttribute : PropertyAttribute
{
    public float min;
    public float max;

    public RangeBarAttribute(float min, float max)
    {
        this.min = min;
        this.max = max;
    }
}"},{"order":8,"type":"paragraph","text":"Next, implement the corresponding PropertyDrawer inside your Editor folder to define the visual representation."},{"order":9,"type":"code","text":"using UnityEditor;
using UnityEngine;

[CustomPropertyDrawer(typeof(RangeBarAttribute))]
public class RangeBarDrawer : PropertyDrawer
{
    public override void OnGUI(Rect position, SerializedProperty property, GUIContent label)
    {
        RangeBarAttribute range = (RangeBarAttribute)attribute;

        EditorGUI.BeginProperty(position, label, property);
        if (property.propertyType == SerializedPropertyType.Float)
        {
            EditorGUI.Slider(position, property, range.min, range.max, label);
        }
        else
        {
            EditorGUI.LabelField(position, label.text, "Use RangeBar with float fields.");
        }
        EditorGUI.EndProperty();
    }
}"},{"order":10,"type":"subheading","text":"Creating a Custom Editor"},{"order":11,"type":"paragraph","text":"While Property Drawers target specific variables, Custom Editors target entire components. They let you override the OnInspectorGUI method to build fully customized layouts, warnings, and buttons."},{"order":12,"type":"code","text":"using UnityEditor;
using UnityEngine;

[CustomEditor(typeof(HealthSystem))]
public class HealthSystemEditor : Editor
{
    public override void OnInspectorGUI()
    {
        HealthSystem health = (HealthSystem)target;

        EditorGUILayout.HelpBox("Manage player health parameters and triggers below.", MessageType.Info);

        // Draw standard inspector fields
        DrawDefaultInspector();

        EditorGUILayout.Space();

        if (GUILayout.Button("Trigger Full Heal"))
        {
            health.RestoreFullHealth();
        }
    }
}"},{"order":13,"type":"subheading","text":"Best Practices"},{"order":14,"type":"bullet_point","text":"Always cache SerializedProperty lookups in OnEnable when building complex custom editors to maximize performance."},{"order":15,"type":"bullet_point","text":"Use EditorGUILayout for automatic layout calculation, but fall back to raw Rect positions inside Property Drawers where precise control is required."},{"order":16,"type":"bullet_point","text":"Wrap modification blocks with EditorGUI.BeginChangeCheck and EditorGUI.EndChangeCheck to record undo actions properly."}]
